5	/**
6	 * @description Handle a new message receive in MQTT.
7	 * @param {string} topic - MQTT topic.
8	 * @param {object} message - The message sent.
9	 * @returns {Promise} Null.
10	 * @example
11	 * handleMqttMessage('stat/zigbee2mqtt/POWER', 'ON');
12	 */
13	async function handleMqttMessage(topic, message) {
14	  // Limit events only on status changes
15	  if (!this.zigbee2mqttConnected) {
16	    this.zigbee2mqttConnected = true;
17	    this.zigbee2mqttRunning = true;
18	    this.zigbee2mqttExist = true;
19	    this.emitStatusEvent();
20	  }
21	
22	  switch (topic) {
23	    case 'zigbee2mqtt/bridge/devices': {
24	      logger.debug('Getting config devices from Zigbee2mqtt');
25	      const devices = JSON.parse(message);
26	
27	      this.discoveredDevices = {};
28	
29	      devices
30	        // Remove Coordinator
31	        .filter((d) => d.type !== 'Coordinator')
32	        // Keep only supported devices from zigbee2mqtt library
33	        .filter((d) => d.supported)
34	        .forEach((device) => {
35	          this.discoveredDevices[device.friendly_name] = device;
36	        });
37	
38	      this.gladys.event.emit(EVENTS.WEBSOCKET.SEND_ALL, {
39	        type: WEBSOCKET_MESSAGE_TYPES.ZIGBEE2MQTT.DISCOVER,
40	        payload: this.getDiscoveredDevices(),
41	      });
42	      break;
43	    }
44	    case 'zigbee2mqtt/bridge/config': {
45	      // Keep only "permit_join" value
46	      const config = JSON.parse(message);
47	      this.z2mPermitJoin = config.permit_join;
48	
49	      logger.debug('Getting config from Zigbee2mqtt : permit_joint =', this.z2mPermitJoin);
50	
51	      this.gladys.event.emit(EVENTS.WEBSOCKET.SEND_ALL, {
52	        type: WEBSOCKET_MESSAGE_TYPES.ZIGBEE2MQTT.PERMIT_JOIN,
53	        payload: this.z2mPermitJoin,
54	      });
55	      break;
56	    }
57	    case 'zigbee2mqtt/bridge/response/permit_join': {
58	      const config = JSON.parse(message);
59	      // If time is 0, permit join is disabled
60	      this.z2mPermitJoin = config.data.time !== undefined && config.data.time > 0;
61	
62	      logger.debug('Getting permit_joint :', this.z2mPermitJoin);
63	
64	      this.gladys.event.emit(EVENTS.WEBSOCKET.SEND_ALL, {
65	        type: WEBSOCKET_MESSAGE_TYPES.ZIGBEE2MQTT.PERMIT_JOIN,
66	        payload: this.z2mPermitJoin,
67	      });
68	      break;
69	    }
70	    case 'zigbee2mqtt/bridge/config/permit_join': {
71	      const config = JSON.parse(message);
72	      this.z2mPermitJoin = config;
73	
74	      logger.debug('Getting permit_joint :', this.z2mPermitJoin);
75	
76	      this.gladys.event.emit(EVENTS.WEBSOCKET.SEND_ALL, {
77	        type: WEBSOCKET_MESSAGE_TYPES.ZIGBEE2MQTT.PERMIT_JOIN,
78	        payload: this.z2mPermitJoin,
79	      });
80	      break;
81	    }
82	    case 'zigbee2mqtt/bridge/response/backup': {
83	      const payload = JSON.parse(message);
84	      await this.saveZ2mBackup(payload);
85	      break;
86	    }
87	    default: {
88	      const splittedTopic = topic.split('/');
89	      if (!message) {
90	        logger.warn(`Zigbee2mqtt topic ${topic} empty message.`);
91	      } else if (splittedTopic.length === 2) {
92	        const deviceName = splittedTopic[1];
