/**
 * @description Get the log stream for a container.
 * @param {string} containerId - Container id.
 * @param {object} [options] - Log options merged with defaults.
 * @returns {Promise<object>} Resolve with the container log stream.
 * @example
 * const stream = await getContainerLogs(containerId, { follow: true });
 */
async function getContainerLogs(containerId, options = {}) {
  if (!this.dockerode) {
    throw new PlatformNotCompatible('SYSTEM_NOT_RUNNING_DOCKER');
  }

  const container = await this.dockerode.getContainer(containerId);
  return container.logs({
    stdout: true,
    stderr: true,
    tail: 100,
    follow: false,
    ...options,
  });
}

module.exports = {
  getContainerLogs,
};
