const READ_LOGS_TIMEOUT_MS = 30 * 1000;
// eslint-disable-next-line no-control-regex
const ANSI_COLOR_REGEX = /\x1B\[[0-9;]*[A-Za-z]/g;
// eslint-disable-next-line no-control-regex
const CONTROL_CHARS_REGEX = /[\x00-\x1F\x7F]/g;

const EZSP_PROTOCOL_VERSION_PREFIX = 'Adapter EZSP protocol version';
const EZSP_PROTOCOL_VERSION_SUFFIX = 'is not supported by Host';

/**
 * @description Read Zigbee2mqtt container logs and detect fatal errors.
 * @param {string} containerId - Container id.
 * @returns {Promise<void>} Resolve when logs have been analyzed.
 * @example
 * await this.readZ2mContainerLogs(containerId);
 */
async function readZ2mContainerLogs(containerId) {
  let stream;
  try {
    stream = await this.gladys.system.getContainerLogs(containerId, { follow: true });
  } catch (e) {
    logger.error('Unable to read Zigbee2mqtt container logs:', e);
    this.z2mContainerError = null;
    this.emitStatusEvent();
    return;
  }

  return new Promise((resolve) => {
    let finished = false;
    let buffer = '';
    let knownError = null;
    let lastErrorMessage = null;
    let timeout;

    const finish = (forceNull = false) => {
      if (finished) {
        return;
      }
      finished = true;
      clearTimeout(timeout);

      if (forceNull) {
        this.z2mContainerError = null;
      } else if (knownError) {
        this.z2mContainerError = knownError;
      } else if (lastErrorMessage !== null) {
        this.z2mContainerError = { code: null, message: lastErrorMessage };
      } else {
        this.z2mContainerError = null;
      }

      this.emitStatusEvent();
      resolve();
    };

    const processLine = (rawLine) => {
      // Strip the first character (Docker stream prefix byte)
      const withoutPrefix = rawLine.slice(1);
      // Strip ANSI color codes and remaining control characters
      const cleaned = withoutPrefix.replace(ANSI_COLOR_REGEX, '').replace(CONTROL_CHARS_REGEX, '');

      // Known error: EZSP protocol version mismatch takes precedence
      if (cleaned.includes(EZSP_PROTOCOL_VERSION_PREFIX) && cleaned.includes(EZSP_PROTOCOL_VERSION_SUFFIX)) {
        knownError = { code: 'EZSP_PROTOCOL_VERSION', message: null };
        stream.destroy();
        finish();
        return;
      }

      // Generic error: keep only the last matched line
      if (/error:/i.test(cleaned)) {
        lastErrorMessage = cleaned.trim();
      }
    };

    timeout = setTimeout(() => {
      stream.destroy();
      finish();
    }, READ_LOGS_TIMEOUT_MS);

    stream.on('data', (chunk) => {
      if (finished) {
        return;
      }
      buffer += chunk.toString();
      const lines = buffer.split('\n');
      buffer = lines.pop();
      lines.forEach(processLine);
    });

    stream.on('end', () => {
      if (buffer.length > 0) {
        processLine(buffer);
        buffer = '';
      }
      finish();
    });

    stream.on('close', () => {
      finish();
    });

    stream.on('error', () => {
      finish(true);
    });
  });
}

module.exports = {
  readZ2mContainerLogs,
};
